<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>点滴 DIĀNDĪ — 精品手冲咖啡</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600;700&family=Noto+Sans+SC:wght@300;400;500&display=swap" rel="stylesheet">
<style>
/* ============================================
   TOKENS
   ============================================ */
:root {
  --obsidian: #0F0E0C;
  --mist: #E6E9ED;
  --copper: #C4813F;
  --copper-dim: rgba(196, 129, 63, 0.15);
  --copper-faint: rgba(196, 129, 63, 0.06);
  --slate: #5C6068;
  --slate-light: #8C9098;
  --cloud: #F2F4F7;
  --ceramic: #FFFFFF;
  --rule: rgba(15, 14, 12, 0.08);

  --display: "Noto Serif SC", "Source Han Serif SC", "Songti SC", "STSong", "SimSun", serif;
  --body: "Noto Sans SC", "Source Han Sans SC", "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", system-ui, -apple-system, sans-serif;

  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 2rem;
  --space-lg: 4rem;
  --space-xl: 6rem;
  --space-2xl: 10rem;

  --max-width: 1100px;
  --max-width-narrow: 720px;
}

/* ============================================
   RESET & BASE
   ============================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--body);
  font-weight: 300;
  line-height: 1.75;
  color: var(--obsidian);
  background: var(--mist);
}

img { display: block; max-width: 100%; }

a {
  color: inherit;
  text-decoration: none;
}

/* ============================================
   TYPOGRAPHY
   ============================================ */
.display {
  font-family: var(--display);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: 0.04em;
}

.display-lg {
  font-size: clamp(4rem, 10vw, 8rem);
}

.display-md {
  font-size: clamp(2rem, 4vw, 3.2rem);
}

.display-sm {
  font-size: clamp(1.2rem, 2vw, 1.6rem);
}

.body-lg {
  font-size: 1.125rem;
  font-weight: 300;
  line-height: 1.8;
}

.body-md {
  font-size: 0.95rem;
  font-weight: 400;
  line-height: 1.7;
}

.body-sm {
  font-size: 0.8rem;
  font-weight: 400;
  line-height: 1.6;
  color: var(--slate);
}

.label {
  font-size: 0.7rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--slate-light);
}

/* ============================================
   LAYOUT
   ============================================ */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-md);
}

.container-narrow {
  max-width: var(--max-width-narrow);
  margin: 0 auto;
  padding: 0 var(--space-md);
}

.section {
  padding: var(--space-xl) 0;
}

.section-tight {
  padding: var(--space-lg) 0;
}

.rule {
  border: none;
  height: 1px;
  background: var(--rule);
  margin: 0;
}

/* ============================================
   HEADER
   ============================================ */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: var(--space-md) 0;
  transition: background 0.3s ease;
}

.header--scrolled {
  background: rgba(230, 233, 237, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-brand {
  font-family: var(--display);
  font-weight: 600;
  font-size: 1.1rem;
  letter-spacing: 0.06em;
}

.header-nav {
  display: flex;
  gap: var(--space-md);
}

.header-nav a {
  font-size: 0.8rem;
  font-weight: 400;
  letter-spacing: 0.05em;
  color: var(--slate);
  transition: color 0.2s;
}

.header-nav a:hover {
  color: var(--copper);
}

/* ============================================
   HERO
   ============================================ */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: var(--space-2xl) var(--space-md);
}

/* Ripple canvas */
.ripple-stage {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.ripple-ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid var(--copper-dim);
  opacity: 0;
  animation: ripple-expand 6s ease-out infinite;
}

.ripple-ring:nth-child(1) { animation-delay: 0s; }
.ripple-ring:nth-child(2) { animation-delay: 1.2s; }
.ripple-ring:nth-child(3) { animation-delay: 2.4s; }
.ripple-ring:nth-child(4) { animation-delay: 3.6s; }
.ripple-ring:nth-child(5) { animation-delay: 4.8s; }

@keyframes ripple-expand {
  0% {
    width: 80px;
    height: 80px;
    opacity: 0.6;
  }
  100% {
    width: min(80vw, 800px);
    height: min(80vw, 800px);
    opacity: 0;
  }
}

/* Pour arcs */
.pour-arcs {
  position: absolute;
  width: min(50vw, 360px);
  height: min(50vw, 360px);
  pointer-events: none;
}

.pour-arc {
  fill: none;
  stroke: var(--copper);
  stroke-width: 0.6;
  stroke-linecap: round;
}

.pour-arc--1 {
  stroke-dasharray: 80 500;
  animation: arc-rotate 16s linear infinite;
}

.pour-arc--2 {
  stroke-dasharray: 50 350;
  animation: arc-rotate 22s linear infinite reverse;
}

.pour-arc--3 {
  stroke-dasharray: 35 250;
  animation: arc-rotate 14s linear infinite;
}

@keyframes arc-rotate {
  to { transform: rotate(360deg); }
  from { transform: rotate(0deg); }
}

/* Hero content */
.hero-content {
  position: relative;
  z-index: 10;
  text-align: center;
}

.hero-brand {
  font-family: var(--display);
  font-size: clamp(5rem, 14vw, 10rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.06em;
  color: var(--obsidian);
  margin-bottom: var(--space-sm);
}

.hero-tagline {
  font-family: var(--body);
  font-weight: 300;
  font-size: clamp(1rem, 2.5vw, 1.4rem);
  color: var(--slate);
  letter-spacing: 0.08em;
  margin-bottom: var(--space-lg);
}

.hero-line {
  width: 40px;
  height: 1px;
  background: var(--copper);
  margin: 0 auto var(--space-lg);
}

.hero-scroll {
  position: absolute;
  bottom: var(--space-lg);
  left: 50%;
  transform: translateX(-50%);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: var(--slate-light);
  animation: scroll-float 2s ease-in-out infinite;
}

@keyframes scroll-float {
  0%, 100% { transform: translateX(-50%) translateY(0); }
  50% { transform: translateX(-50%) translateY(6px); }
}

/* ============================================
   FEATURED COFFEE
   ============================================ */
.featured {
  background: var(--ceramic);
}

.featured-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  align-items: center;
}

.featured-visual {
  position: relative;
  aspect-ratio: 1;
  background: var(--copper-faint);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.featured-cup {
  width: 60%;
  height: 60%;
  position: relative;
}

/* CSS-drawn coffee dripper */
.dripper {
  width: 100%;
  height: 100%;
  position: relative;
}

.dripper-body {
  position: absolute;
  top: 15%;
  left: 15%;
  width: 70%;
  height: 55%;
  border: 2px solid var(--copper);
  border-radius: 0 0 8% 8%;
  background: linear-gradient(
    180deg,
    rgba(196, 129, 63, 0.04) 0%,
    rgba(196, 129, 63, 0.12) 100%
  );
}

.dripper-ridge {
  position: absolute;
  top: 13%;
  left: 12%;
  width: 76%;
  height: 3px;
  background: var(--copper);
  border-radius: 2px;
}

.dripper-neck {
  position: absolute;
  bottom: 25%;
  left: 42%;
  width: 16%;
  height: 18%;
  border-left: 1.5px solid var(--copper);
  border-right: 1.5px solid var(--copper);
}

.dripper-drop {
  position: absolute;
  bottom: 12%;
  left: 47%;
  width: 6%;
  height: 10%;
  background: #3D2B1F;
  border-radius: 50% 50% 50% 50% / 30% 30% 70% 70%;
  animation: drip-fall 2.5s ease-in infinite;
}

.dripper-drop:nth-child(5) { animation-delay: 0.8s; left: 46%; opacity: 0.6; }
.dripper-drop:nth-child(6) { animation-delay: 1.6s; left: 48%; opacity: 0.4; }

@keyframes drip-fall {
  0% {
    transform: translateY(-60%);
    opacity: 0;
  }
  20% {
    opacity: 1;
  }
  60% {
    transform: translateY(40%);
    opacity: 0.8;
  }
  100% {
    transform: translateY(120%);
    opacity: 0;
  }
}

.dripper-steam {
  position: absolute;
  top: 5%;
  left: 35%;
  width: 2px;
  height: 20%;
  background: var(--slate-light);
  opacity: 0.3;
  border-radius: 1px;
  animation: steam-rise 3s ease-out infinite;
}

.dripper-steam:nth-child(8) { left: 50%; animation-delay: 1s; }
.dripper-steam:nth-child(9) { left: 60%; animation-delay: 2s; opacity: 0.2; }

@keyframes steam-rise {
  0% {
    transform: translateY(0) scaleX(1);
    opacity: 0.3;
  }
  100% {
    transform: translateY(-100%) scaleX(2.5);
    opacity: 0;
  }
}

.featured-info {
  padding: var(--space-lg) 0;
}

.featured-label {
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--copper);
  margin-bottom: var(--space-sm);
}

.featured-name {
  font-family: var(--display);
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 600;
  line-height: 1.2;
  margin-bottom: var(--space-sm);
  color: var(--obsidian);
}

.featured-origin {
  font-size: 0.9rem;
  color: var(--slate);
  margin-bottom: var(--space-md);
}

.featured-notes {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-xs);
  margin-bottom: var(--space-lg);
}

.note-tag {
  display: inline-block;
  padding: 0.3rem 0.9rem;
  font-size: 0.78rem;
  font-weight: 400;
  color: var(--slate);
  border: 1px solid var(--rule);
  border-radius: 100px;
  transition: border-color 0.3s, color 0.3s;
}

.note-tag:hover {
  border-color: var(--copper);
  color: var(--copper);
}

/* Specs table */
.specs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: var(--rule);
  margin-top: var(--space-md);
}

.spec-item {
  background: var(--ceramic);
  padding: var(--space-sm);
}

.spec-label {
  font-size: 0.65rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--slate-light);
  margin-bottom: 0.25rem;
}

.spec-value {
  font-size: 0.85rem;
  font-weight: 400;
  color: var(--obsidian);
}

/* ============================================
   RITUAL SECTION
   ============================================ */
.ritual {
  background: var(--mist);
}

.ritual-head {
  text-align: center;
  margin-bottom: var(--space-xl);
}

.ritual-title {
  font-family: var(--display);
  font-size: clamp(1.8rem, 3vw, 2.6rem);
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.ritual-sub {
  color: var(--slate);
  font-weight: 300;
}

.ritual-flow {
  display: flex;
  gap: 0;
  align-items: flex-start;
  justify-content: center;
  position: relative;
}

.ritual-step {
  flex: 1;
  max-width: 220px;
  text-align: center;
  position: relative;
}

.ritual-step + .ritual-step::before {
  content: '';
  position: absolute;
  top: 40px;
  left: -50%;
  width: 100%;
  height: 1px;
  background: var(--copper-dim);
}

.ritual-icon {
  width: 80px;
  height: 80px;
  margin: 0 auto var(--space-sm);
  border-radius: 50%;
  border: 1px solid var(--copper-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  z-index: 2;
  background: var(--mist);
  transition: border-color 0.4s, background 0.4s;
}

.ritual-step:hover .ritual-icon {
  border-color: var(--copper);
  background: var(--copper-faint);
}

.ritual-icon-inner {
  font-size: 1.5rem;
  color: var(--slate-light);
  transition: color 0.4s;
}

.ritual-step:hover .ritual-icon-inner {
  color: var(--copper);
}

.ritual-phase {
  font-family: var(--display);
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 0.3rem;
  letter-spacing: 0.04em;
}

.ritual-action {
  font-size: 0.8rem;
  color: var(--slate);
  font-weight: 300;
}

/* ============================================
   DETAILS SECTION
   ============================================ */
.details {
  background: var(--ceramic);
}

.details-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  align-items: start;
}

.details-block {
  padding: var(--space-md) 0;
}

.details-heading {
  font-family: var(--display);
  font-size: 1.3rem;
  font-weight: 600;
  margin-bottom: var(--space-md);
  padding-bottom: var(--space-sm);
  border-bottom: 1px solid var(--copper-dim);
}

.details-text {
  color: var(--slate);
  line-height: 1.9;
  margin-bottom: var(--space-sm);
}

.details-list {
  list-style: none;
}

.details-list li {
  padding: 0.5rem 0;
  border-bottom: 1px solid var(--rule);
  font-size: 0.9rem;
  display: flex;
  justify-content: space-between;
}

.details-list .list-key {
  color: var(--slate-light);
  font-weight: 400;
}

.details-list .list-val {
  font-weight: 500;
}

/* ============================================
   CTA
   ============================================ */
.cta {
  background: var(--obsidian);
  color: var(--ceramic);
  text-align: center;
}

.cta-title {
  font-family: var(--display);
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  font-weight: 600;
  line-height: 1.2;
  margin-bottom: var(--space-sm);
  letter-spacing: 0.04em;
}

.cta-sub {
  color: var(--slate-light);
  font-weight: 300;
  max-width: 500px;
  margin: 0 auto var(--space-lg);
}

.cta-price {
  font-family: var(--display);
  font-size: 2.5rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
  color: var(--copper);
}

.cta-unit {
  font-size: 0.8rem;
  color: var(--slate-light);
  margin-bottom: var(--space-lg);
}

.btn {
  display: inline-block;
  padding: 0.85rem 2.5rem;
  font-family: var(--body);
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  border: 1px solid var(--copper);
  color: var(--copper);
  background: transparent;
  cursor: pointer;
  transition: all 0.35s ease;
  position: relative;
  overflow: hidden;
}

.btn::before {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--copper);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.35s ease;
  z-index: 0;
}

.btn:hover::before {
  transform: scaleX(1);
}

.btn span {
  position: relative;
  z-index: 1;
  transition: color 0.35s ease;
}

.btn:hover span {
  color: var(--ceramic);
}

.btn--inverse {
  border-color: var(--copper);
  color: var(--ceramic);
  background: var(--copper);
}

.btn--inverse::before {
  background: var(--ceramic);
}

.btn--inverse:hover span {
  color: var(--copper);
}

/* ============================================
   FOOTER
   ============================================ */
.footer {
  background: var(--obsidian);
  border-top: 1px solid rgba(255,255,255,0.06);
  padding: var(--space-md) 0;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-brand {
  font-family: var(--display);
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: var(--ceramic);
}

.footer-copy {
  font-size: 0.7rem;
  color: var(--slate-light);
  letter-spacing: 0.05em;
}

/* ============================================
   REVEAL ANIMATIONS
   ============================================ */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.8s ease, transform 0.8s ease;
}

.reveal--visible {
  opacity: 1;
  transform: translateY(0);
}

/* ============================================
   REDUCED MOTION
   ============================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .reveal {
    opacity: 1;
    transform: none;
  }
}

/* ============================================
   RESPONSIVE
   ============================================ */
@media (max-width: 768px) {
  :root {
    --space-xl: 3rem;
    --space-2xl: 5rem;
  }

  .header-nav {
    gap: var(--space-sm);
  }

  .featured-grid {
    grid-template-columns: 1fr;
    gap: var(--space-md);
  }

  .featured-visual {
    aspect-ratio: 4/3;
  }

  .ritual-flow {
    flex-direction: column;
    align-items: center;
    gap: var(--space-lg);
  }

  .ritual-step {
    max-width: 100%;
    width: 100%;
  }

  .ritual-step + .ritual-step::before {
    display: none;
  }

  .details-grid {
    grid-template-columns: 1fr;
    gap: var(--space-md);
  }

  .specs {
    grid-template-columns: 1fr;
  }

  .hero-brand {
    font-size: clamp(3.5rem, 12vw, 6rem);
  }

  .footer-inner {
    flex-direction: column;
    gap: var(--space-xs);
    text-align: center;
  }
}

@media (max-width: 480px) {
  .hero-brand {
    font-size: 3rem;
  }

  .featured-visual {
    aspect-ratio: 1;
  }

  .ritual-icon {
    width: 64px;
    height: 64px;
  }

  .pour-arcs {
    width: 70vw;
    height: 70vw;
  }
}
</style>
</head>
<body>

<!-- Header -->
<header class="header" id="header">
  <div class="header-inner">
    <a href="#" class="header-brand">点滴 DIĀNDĪ</a>
    <nav class="header-nav">
      <a href="#featured">臻选</a>
      <a href="#ritual">冲煮</a>
      <a href="#details">溯源</a>
    </nav>
  </div>
</header>

<!-- Hero -->
<section class="hero" id="hero">
  <div class="ripple-stage" aria-hidden="true">
    <div class="ripple-ring"></div>
    <div class="ripple-ring"></div>
    <div class="ripple-ring"></div>
    <div class="ripple-ring"></div>
    <div class="ripple-ring"></div>
  </div>

  <svg class="pour-arcs" viewBox="0 0 360 360" aria-hidden="true">
    <circle cx="180" cy="180" r="160" class="pour-arc pour-arc--1" />
    <circle cx="180" cy="180" r="120" class="pour-arc pour-arc--2" />
    <circle cx="180" cy="180" r="80"  class="pour-arc pour-arc--3" />
  </svg>

  <div class="hero-content reveal" data-reveal>
    <h1 class="hero-brand">点滴</h1>
    <p class="hero-tagline">时间落入杯中</p>
    <div class="hero-line"></div>
  </div>

  <div class="hero-scroll">↓</div>
</section>

<hr class="rule">

<!-- Featured Coffee -->
<section class="section featured" id="featured">
  <div class="container">
    <div class="featured-grid">
      <div class="featured-visual reveal" data-reveal>
        <div class="featured-cup">
          <div class="dripper">
            <div class="dripper-body"></div>
            <div class="dripper-ridge"></div>
            <div class="dripper-neck"></div>
            <div class="dripper-steam"></div>
            <div class="dripper-steam"></div>
            <div class="dripper-steam"></div>
            <div class="dripper-drop"></div>
            <div class="dripper-drop"></div>
            <div class="dripper-drop"></div>
          </div>
        </div>
